runtimeConditionals.source:
isWindowExpired ? (
                    <ReturnWindowExpired
                        orderNumber={formatOrderNumber(order.orderNumber)}
                        deadline={deadline}
                    />
                ) : !eligibility.valid ? (
                    <NotEligibleMessage
                        orderId={order._id}
                        orderNumber={formatOrderNumber(order.orderNumber)}
                        message={eligibility.error || 'This order is not eligible for return.'}
                    />
                ) : (
                    <div className="flex flex-col gap-6">
                        <ReturnRequestForm order={order} />
                        <ReturnPolicyReminder />
                    </div>
                )
